 17→// nonAlphanumericRegex matches any non-alphanumeric character for path sanitization.
 18→// Same pattern as claudecode.SanitizePathForClaude — duplicated to avoid cross-package dependency.
 19→var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
 20→
 21→func sanitizeRepoPath(path string) string {
 22→	return nonAlphanumericRegex.ReplaceAllString(path, "-")
 23→}
