 30→// FactoryAIDroidAgent implements the agent.Agent interface for Factory AI Droid.
 31→//
 32→//nolint:revive // FactoryAIDroidAgent is clearer than Agent in this context
 33→type FactoryAIDroidAgent struct{}
 34→
 35→// NewFactoryAIDroidAgent creates a new Factory AI Droid agent instance.
 36→func NewFactoryAIDroidAgent() agent.Agent {
 37→	return &FactoryAIDroidAgent{}
 38→}
 39→
 40→// Name returns the agent registry key.
 41→func (f *FactoryAIDroidAgent) Name() agent.AgentName { return agent.AgentNameFactoryAIDroid }
 42→
 43→// Type returns the agent type identifier.
 44→func (f *FactoryAIDroidAgent) Type() agent.AgentType { return agent.AgentTypeFactoryAIDroid }
 45→
 46→// Description returns a human-readable description.
 47→func (f *FactoryAIDroidAgent) Description() string {
 48→	return "Factory AI Droid - agent-native development platform"
 49→}
 50→
 51→// IsPreview returns true as Factory AI Droid integration is in preview.
 52→func (f *FactoryAIDroidAgent) IsPreview() bool { return true }
 53→
 54→// ProtectedDirs returns directories that Factory AI Droid uses for config/state.
 55→func (f *FactoryAIDroidAgent) ProtectedDirs() []string { return []string{".factory"} }
 56→
 57→// DetectPresence checks if Factory AI Droid is configured in the repository.
 58→func (f *FactoryAIDroidAgent) DetectPresence() (bool, error) {
 59→	repoRoot, err := paths.RepoRoot()
 60→	if err != nil {
 61→		repoRoot = "."
 62→	}
 63→	if _, err := os.Stat(filepath.Join(repoRoot, ".factory")); err == nil {
 64→		return true, nil
 65→	}
 66→	return false, nil
 67→}
