 69→// ReadTranscript reads the raw JSONL transcript bytes for a session.
 70→func (f *FactoryAIDroidAgent) ReadTranscript(sessionRef string) ([]byte, error) {
 71→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
 72→	if err != nil {
 73→		return nil, fmt.Errorf("failed to read transcript: %w", err)
 74→	}
 75→	return data, nil
 76→}
 77→
 78→// ChunkTranscript splits a JSONL transcript at line boundaries.
 79→func (f *FactoryAIDroidAgent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
 80→	chunks, err := agent.ChunkJSONL(content, maxSize)
 81→	if err != nil {
 82→		return nil, fmt.Errorf("failed to chunk transcript: %w", err)
 83→	}
 84→	return chunks, nil
 85→}
 86→
 87→// ReassembleTranscript concatenates JSONL chunks with newlines.
 88→func (f *FactoryAIDroidAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
 89→	return agent.ReassembleJSONL(chunks), nil
 90→}
