 92→// GetHookConfigPath returns the path to Factory AI Droid's hook config file.
 93→func (f *FactoryAIDroidAgent) GetHookConfigPath() string { return ".factory/settings.json" }
 94→
 95→// SupportsHooks returns true as Factory AI Droid supports lifecycle hooks.
 96→func (f *FactoryAIDroidAgent) SupportsHooks() bool { return true }
