 98→// ParseHookInput parses Factory AI Droid hook input from stdin.
 99→func (f *FactoryAIDroidAgent) ParseHookInput(_ agent.HookType, r io.Reader) (*agent.HookInput, error) {
100→	raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](r)
101→	if err != nil {
102→		return nil, err
103→	}
104→	return &agent.HookInput{
105→		SessionID:  raw.SessionID,
106→		SessionRef: raw.TranscriptPath,
107→	}, nil
108→}
109→
110→// GetSessionID extracts the session ID from hook input.
111→func (f *FactoryAIDroidAgent) GetSessionID(input *agent.HookInput) string { return input.SessionID }
112→
113→// GetSessionDir returns the directory where Factory AI Droid stores session transcripts.
114→// Path: ~/.factory/sessions/<sanitized-repo-path>/
115→func (f *FactoryAIDroidAgent) GetSessionDir(repoPath string) (string, error) {
116→	if override := os.Getenv("ENTIRE_TEST_DROID_PROJECT_DIR"); override != "" {
117→		return override, nil
118→	}
119→	homeDir, err := os.UserHomeDir()
120→	if err != nil {
121→		return "", fmt.Errorf("failed to get home directory: %w", err)
122→	}
123→	projectDir := sanitizeRepoPath(repoPath)
124→	return filepath.Join(homeDir, ".factory", "sessions", projectDir), nil
125→}
