127→// ResolveSessionFile returns the path to a Factory AI Droid session file.
128→func (f *FactoryAIDroidAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
129→	return filepath.Join(sessionDir, agentSessionID+".jsonl")
130→}
131→
132→// ReadSession reads a session from Factory AI Droid's storage (JSONL transcript file).
133→// The session data is stored in NativeData as raw JSONL bytes.
134→// ModifiedFiles is computed by parsing the transcript.
135→func (f *FactoryAIDroidAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
136→	if input.SessionRef == "" {
137→		return nil, errors.New("session reference (transcript path) is required")
138→	}
139→
140→	data, err := os.ReadFile(input.SessionRef)
141→	if err != nil {
142→		return nil, fmt.Errorf("failed to read transcript: %w", err)
143→	}
144→
145→	lines, err := ParseDroidTranscriptFromBytes(data, 0)
146→	if err != nil {
147→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
148→	}
149→
150→	return &agent.AgentSession{
151→		SessionID:     input.SessionID,
152→		AgentName:     f.Name(),
153→		SessionRef:    input.SessionRef,
154→		StartTime:     time.Now(),
155→		NativeData:    data,
156→		ModifiedFiles: ExtractModifiedFiles(lines),
157→	}, nil
158→}
159→
160→// WriteSession writes a session to Factory AI Droid's storage (JSONL transcript file).
161→// Uses the NativeData field which contains raw JSONL bytes.
162→func (f *FactoryAIDroidAgent) WriteSession(session *agent.AgentSession) error {
163→	if session == nil {
164→		return errors.New("session is nil")
165→	}
166→
167→	if session.AgentName != "" && session.AgentName != f.Name() {
168→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, f.Name())
169→	}
170→
171→	if session.SessionRef == "" {
172→		return errors.New("session reference (transcript path) is required")
173→	}
174→
175→	if len(session.NativeData) == 0 {
176→		return errors.New("session has no native data to write")
177→	}
178→
179→	if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o750); err != nil {
180→		return fmt.Errorf("failed to create session directory: %w", err)
181→	}
182→
183→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
184→		return fmt.Errorf("failed to write transcript: %w", err)
185→	}
186→
187→	return nil
188→}
