 13→// TestDetectPresence uses t.Chdir so it cannot be parallel.
 14→func TestDetectPresence(t *testing.T) {
 15→	t.Run("factory directory exists", func(t *testing.T) {
 16→		tempDir := t.TempDir()
 17→		t.Chdir(tempDir)
 18→
 19→		if err := os.Mkdir(".factory", 0o755); err != nil {
 20→			t.Fatalf("failed to create .factory: %v", err)
 21→		}
 22→
 23→		ag := &FactoryAIDroidAgent{}
 24→		present, err := ag.DetectPresence()
 25→		if err != nil {
 26→			t.Fatalf("DetectPresence() error = %v", err)
 27→		}
 28→		if !present {
 29→			t.Error("DetectPresence() = false, want true")
 30→		}
 31→	})
 32→
 33→	t.Run("no factory directory", func(t *testing.T) {
 34→		tempDir := t.TempDir()
 35→		t.Chdir(tempDir)
 36→
 37→		ag := &FactoryAIDroidAgent{}
 38→		present, err := ag.DetectPresence()
 39→		if err != nil {
 40→			t.Fatalf("DetectPresence() error = %v", err)
 41→		}
 42→		if present {
 43→			t.Error("DetectPresence() = true, want false")
 44→		}
 45→	})
 46→}
