 79→func TestChunkTranscript_LargeContent(t *testing.T) {
 80→	t.Parallel()
 81→	ag := &FactoryAIDroidAgent{}
 82→
 83→	// Build multi-line JSONL that exceeds a small maxSize
 84→	var lines []string
 85→	for i := range 50 {
 86→		lines = append(lines, fmt.Sprintf(`{"role":"user","content":"message %d %s"}`, i, strings.Repeat("x", 200)))
 87→	}
 88→	content := []byte(strings.Join(lines, "\n"))
 89→
 90→	maxSize := 2000
 91→	chunks, err := ag.ChunkTranscript(content, maxSize)
 92→	if err != nil {
 93→		t.Fatalf("ChunkTranscript() error = %v", err)
 94→	}
 95→	if len(chunks) < 2 {
 96→		t.Errorf("Expected at least 2 chunks for large content, got %d", len(chunks))
 97→	}
 98→
 99→	// Verify each chunk is valid JSONL (each line is valid JSON)
100→	for i, chunk := range chunks {
101→		chunkLines := strings.Split(string(chunk), "\n")
102→		for j, line := range chunkLines {
103→			if line == "" {
104→				continue
105→			}
106→			if line[0] != '{' {
107→				t.Errorf("Chunk %d, line %d doesn't look like JSON: %q", i, j, line[:min(len(line), 40)])
108→			}
109→		}
110→	}
111→}
