195→func TestReadSession(t *testing.T) {
196→	t.Parallel()
197→
198→	tmpDir := t.TempDir()
199→	transcriptPath := filepath.Join(tmpDir, "transcript.jsonl")
200→
201→	// Write a Droid-format JSONL transcript with a file-modifying tool call
202→	content := `{"type":"message","id":"msg1","message":{"role":"user","content":[{"type":"text","text":"create a file"}]}}
203→{"type":"message","id":"msg2","message":{"role":"assistant","content":[{"type":"tool_use","name":"Write","input":{"file_path":"hello.txt","content":"hi"}}]}}`
204→	if err := os.WriteFile(transcriptPath, []byte(content), 0o644); err != nil {
205→		t.Fatalf("failed to write transcript: %v", err)
206→	}
207→
208→	ag := &FactoryAIDroidAgent{}
209→	session, err := ag.ReadSession(&agent.HookInput{
210→		SessionID:  "test-session-123",
211→		SessionRef: transcriptPath,
212→	})
213→	if err != nil {
214→		t.Fatalf("ReadSession() error = %v", err)
215→	}
216→
217→	if session.SessionID != "test-session-123" {
218→		t.Errorf("SessionID = %q, want %q", session.SessionID, "test-session-123")
219→	}
220→	if session.AgentName != agent.AgentNameFactoryAIDroid {
221→		t.Errorf("AgentName = %q, want %q", session.AgentName, agent.AgentNameFactoryAIDroid)
222→	}
223→	if session.SessionRef != transcriptPath {
224→		t.Errorf("SessionRef = %q, want %q", session.SessionRef, transcriptPath)
225→	}
226→	if len(session.NativeData) == 0 {
227→		t.Error("NativeData should not be empty")
228→	}
229→	if len(session.ModifiedFiles) == 0 {
230→		t.Error("ModifiedFiles should contain at least one file")
231→	}
232→}
