329→func TestReadWriteSession_RoundTrip(t *testing.T) {
330→	t.Parallel()
331→
332→	tmpDir := t.TempDir()
333→	originalPath := filepath.Join(tmpDir, "original.jsonl")
334→	restoredPath := filepath.Join(tmpDir, "restored.jsonl")
335→
336→	content := `{"type":"message","id":"msg1","message":{"role":"user","content":[{"type":"text","text":"hello"}]}}
337→{"type":"message","id":"msg2","message":{"role":"assistant","content":[{"type":"text","text":"hi there"}]}}`
338→	if err := os.WriteFile(originalPath, []byte(content), 0o644); err != nil {
339→		t.Fatalf("failed to write original: %v", err)
340→	}
341→
342→	ag := &FactoryAIDroidAgent{}
343→
344→	// Read from original location
345→	session, err := ag.ReadSession(&agent.HookInput{
346→		SessionID:  "round-trip-test",
347→		SessionRef: originalPath,
348→	})
349→	if err != nil {
350→		t.Fatalf("ReadSession() error = %v", err)
351→	}
352→
353→	// Write to new location
354→	session.SessionRef = restoredPath
355→	if err := ag.WriteSession(session); err != nil {
356→		t.Fatalf("WriteSession() error = %v", err)
357→	}
358→
359→	// Verify content matches
360→	restored, err := os.ReadFile(restoredPath)
361→	if err != nil {
362→		t.Fatalf("failed to read restored: %v", err)
363→	}
364→	if string(restored) != content {
365→		t.Errorf("round-trip mismatch:\n got: %q\nwant: %q", string(restored), content)
366→	}
367→}
