256→// parseHookType parses a specific hook type from rawHooks into the target slice.
257→// Silently ignores parse errors (leaves target unchanged).
258→func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]FactoryHookMatcher) {
259→	if data, ok := rawHooks[hookType]; ok {
260→		//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
261→		json.Unmarshal(data, target)
262→	}
263→}
264→
265→// marshalHookType marshals a hook type back to rawHooks.
266→// If the slice is empty, removes the key from rawHooks.
267→func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, matchers []FactoryHookMatcher) {
268→	if len(matchers) == 0 {
269→		delete(rawHooks, hookType)
270→		return
271→	}
272→	data, err := json.Marshal(matchers)
273→	if err != nil {
274→		return // Silently ignore marshal errors (shouldn't happen)
275→	}
276→	rawHooks[hookType] = data
277→}
