279→// UninstallHooks removes Entire hooks from Factory AI Droid settings.
280→func (f *FactoryAIDroidAgent) UninstallHooks() error {
281→	// Use repo root to find .factory directory when run from a subdirectory
282→	repoRoot, err := paths.RepoRoot()
283→	if err != nil {
284→		repoRoot = "." // Fallback to CWD if not in a git repo
285→	}
286→	settingsPath := filepath.Join(repoRoot, ".factory", FactorySettingsFileName)
287→	data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
288→	if err != nil {
289→		return nil //nolint:nilerr // No settings file means nothing to uninstall
290→	}
291→
292→	var rawSettings map[string]json.RawMessage
293→	if err := json.Unmarshal(data, &rawSettings); err != nil {
294→		return fmt.Errorf("failed to parse settings.json: %w", err)
295→	}
296→
297→	// rawHooks preserves unknown hook types
298→	var rawHooks map[string]json.RawMessage
299→	if hooksRaw, ok := rawSettings["hooks"]; ok {
300→		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
301→			return fmt.Errorf("failed to parse hooks: %w", err)
302→		}
303→	}
304→	if rawHooks == nil {
305→		rawHooks = make(map[string]json.RawMessage)
306→	}
307→
308→	// Parse only the hook types we need to modify
309→	var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse, preCompact []FactoryHookMatcher
310→	parseHookType(rawHooks, "SessionStart", &sessionStart)
311→	parseHookType(rawHooks, "SessionEnd", &sessionEnd)
312→	parseHookType(rawHooks, "Stop", &stop)
313→	parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
314→	parseHookType(rawHooks, "PreToolUse", &preToolUse)
315→	parseHookType(rawHooks, "PostToolUse", &postToolUse)
316→	parseHookType(rawHooks, "PreCompact", &preCompact)
317→
318→	// Remove Entire hooks from all hook types
319→	sessionStart = removeEntireHooks(sessionStart)
320→	sessionEnd = removeEntireHooks(sessionEnd)
321→	stop = removeEntireHooks(stop)
322→	userPromptSubmit = removeEntireHooks(userPromptSubmit)
323→	preToolUse = removeEntireHooksFromMatchers(preToolUse)
324→	postToolUse = removeEntireHooksFromMatchers(postToolUse)
325→	preCompact = removeEntireHooks(preCompact)
326→
327→	// Marshal modified hook types back to rawHooks
328→	marshalHookType(rawHooks, "SessionStart", sessionStart)
329→	marshalHookType(rawHooks, "SessionEnd", sessionEnd)
330→	marshalHookType(rawHooks, "Stop", stop)
331→	marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
332→	marshalHookType(rawHooks, "PreToolUse", preToolUse)
333→	marshalHookType(rawHooks, "PostToolUse", postToolUse)
334→	marshalHookType(rawHooks, "PreCompact", preCompact)
335→
336→	// Also remove the metadata deny rule from permissions
337→	var rawPermissions map[string]json.RawMessage
338→	if permRaw, ok := rawSettings["permissions"]; ok {
339→		if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
340→			// If parsing fails, just skip permissions cleanup
341→			rawPermissions = nil
342→		}
343→	}
344→
345→	if rawPermissions != nil {
346→		if denyRaw, ok := rawPermissions["deny"]; ok {
347→			var denyRules []string
348→			if err := json.Unmarshal(denyRaw, &denyRules); err == nil {
349→				// Filter out the metadata deny rule
350→				filteredRules := make([]string, 0, len(denyRules))
351→				for _, rule := range denyRules {
352→					if rule != metadataDenyRule {
353→						filteredRules = append(filteredRules, rule)
354→					}
355→				}
356→				if len(filteredRules) > 0 {
357→					denyJSON, err := json.Marshal(filteredRules)
358→					if err == nil {
359→						rawPermissions["deny"] = denyJSON
360→					}
361→				} else {
362→					// Remove empty deny array
363→					delete(rawPermissions, "deny")
364→				}
365→			}
366→		}
367→
368→		// If permissions is empty, remove it entirely
369→		if len(rawPermissions) > 0 {
370→			permJSON, err := json.Marshal(rawPermissions)
371→			if err == nil {
372→				rawSettings["permissions"] = permJSON
373→			}
374→		} else {
375→			delete(rawSettings, "permissions")
376→		}
377→	}
378→
379→	// Marshal hooks back (preserving unknown hook types)
380→	if len(rawHooks) > 0 {
381→		hooksJSON, err := json.Marshal(rawHooks)
382→		if err != nil {
383→			return fmt.Errorf("failed to marshal hooks: %w", err)
384→		}
385→		rawSettings["hooks"] = hooksJSON
386→	} else {
387→		delete(rawSettings, "hooks")
388→	}
389→
390→	// Write back
391→	output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
392→	if err != nil {
393→		return fmt.Errorf("failed to marshal settings: %w", err)
394→	}
395→	if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
396→		return fmt.Errorf("failed to write settings.json: %w", err)
397→	}
398→	return nil
399→}
