436→// Helper functions for hook management
437→
438→func hookCommandExists(matchers []FactoryHookMatcher, command string) bool {
439→	for _, matcher := range matchers {
440→		for _, hook := range matcher.Hooks {
441→			if hook.Command == command {
442→				return true
443→			}
444→		}
445→	}
446→	return false
447→}
448→
449→func hookCommandExistsWithMatcher(matchers []FactoryHookMatcher, matcherName, command string) bool {
450→	for _, matcher := range matchers {
451→		if matcher.Matcher == matcherName {
452→			for _, hook := range matcher.Hooks {
453→				if hook.Command == command {
454→					return true
455→				}
456→			}
457→		}
458→	}
459→	return false
460→}
461→
462→func addHookToMatcher(matchers []FactoryHookMatcher, matcherName, command string) []FactoryHookMatcher {
463→	entry := FactoryHookEntry{
464→		Type:    "command",
465→		Command: command,
466→	}
467→
468→	// If no matcher name, add to a matcher with empty string
469→	if matcherName == "" {
470→		for i, matcher := range matchers {
471→			if matcher.Matcher == "" {
472→				matchers[i].Hooks = append(matchers[i].Hooks, entry)
473→				return matchers
474→			}
475→		}
476→		return append(matchers, FactoryHookMatcher{
477→			Matcher: "",
478→			Hooks:   []FactoryHookEntry{entry},
479→		})
480→	}
481→
482→	// Find or create matcher with the given name
483→	for i, matcher := range matchers {
484→		if matcher.Matcher == matcherName {
485→			matchers[i].Hooks = append(matchers[i].Hooks, entry)
486→			return matchers
487→		}
488→	}
489→
490→	return append(matchers, FactoryHookMatcher{
491→		Matcher: matcherName,
492→		Hooks:   []FactoryHookEntry{entry},
493→	})
494→}
495→
496→// isEntireHook checks if a command is an Entire hook (old or new format)
497→func isEntireHook(command string) bool {
498→	for _, prefix := range entireHookPrefixes {
499→		if strings.HasPrefix(command, prefix) {
500→			return true
501→		}
502→	}
503→	return false
504→}
505→
506→// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
507→func removeEntireHooks(matchers []FactoryHookMatcher) []FactoryHookMatcher {
508→	result := make([]FactoryHookMatcher, 0, len(matchers))
509→	for _, matcher := range matchers {
510→		filteredHooks := make([]FactoryHookEntry, 0, len(matcher.Hooks))
511→		for _, hook := range matcher.Hooks {
512→			if !isEntireHook(hook.Command) {
513→				filteredHooks = append(filteredHooks, hook)
514→			}
515→		}
516→		// Only keep the matcher if it has hooks remaining
517→		if len(filteredHooks) > 0 {
518→			matcher.Hooks = filteredHooks
519→			result = append(result, matcher)
520→		}
521→	}
522→	return result
523→}
524→
525→// removeEntireHooksFromMatchers removes Entire hooks from tool-use matchers (PreToolUse, PostToolUse)
526→// This handles the nested structure where hooks are grouped by tool matcher (e.g., "Task")
527→func removeEntireHooksFromMatchers(matchers []FactoryHookMatcher) []FactoryHookMatcher {
528→	// Same logic as removeEntireHooks - both work on the same structure
529→	return removeEntireHooks(matchers)
530→}
