 703→
 704→	t.Run("ReadSession parses transcript and computes ModifiedFiles", func(t *testing.T) {
 705→		t.Parallel()
 706→		env := NewTestEnv(t)
 707→		env.InitRepo()
 708→
 709→		// Create a Gemini transcript file (JSON format)
 710→		// Gemini uses "type" field with values "user" or "gemini", and "toolCalls" array with "args"
 711→		transcriptPath := filepath.Join(env.RepoDir, "test-transcript.json")
 712→		transcriptContent := `{
 713→  "messages": [
 714→    {"type": "user", "content": "Fix the bug"},
 715→    {"type": "gemini", "content": "", "toolCalls": [{"name": "write_file", "args": {"file_path": "main.go"}}]},
 716→    {"type": "gemini", "content": "", "toolCalls": [{"name": "edit_file", "args": {"file_path": "util.go"}}]}
 717→  ]
 718→}`
 719→		if err := os.WriteFile(transcriptPath, []byte(transcriptContent), 0o644); err != nil {
 720→			t.Fatalf("failed to write transcript: %v", err)
 721→		}
 722→
 723→		ag, _ := agent.Get("gemini")
 724→		session, err := ag.ReadSession(&agent.HookInput{
 725→			SessionID:  "test-session",
 726→			SessionRef: transcriptPath,
 727→		})
 728→		if err != nil {
 729→			t.Fatalf("ReadSession() error = %v", err)
 730→		}
 731→
 732→		// Verify session metadata
 733→		if session.SessionID != "test-session" {
 734→			t.Errorf("SessionID = %q, want %q", session.SessionID, "test-session")
 735→		}
 736→		if session.AgentName != "gemini" {
 737→			t.Errorf("AgentName = %q, want %q", session.AgentName, "gemini")
 738→		}
 739→
 740→		// Verify NativeData is populated
 741→		if len(session.NativeData) == 0 {
 742→			t.Error("NativeData is empty, want transcript content")
 743→		}
 744→
 745→		// Verify ModifiedFiles computed
 746→		if len(session.ModifiedFiles) != 2 {
 747→			t.Errorf("ModifiedFiles = %v, want 2 files (main.go, util.go)", session.ModifiedFiles)
 748→		}
 749→	})
